beam-search.pseudocode:
def beam_search(start, expand, score, k, depth):
    beam = [start]
    for _ in range(depth):
        candidates = []
        for node in beam:
            candidates.extend(expand(node))  # 후속 노드 생성
        if not candidates:
            break
        candidates.sort(key=score, reverse=True)
        beam = candidates[:k]  # 상위 k개만 유지, 나머지 폐기
    return max(beam, key=score)
# 유망 경로를 버릴 수 있어 완전성·최적성 미보장

behavior-tree.pseudocode:
def tick(node, bb):  # bb: 블랙보드(공유 상태)
    if node.kind in ('action', 'condition'):
        return node.run(bb)  # SUCCESS·FAILURE·RUNNING
    if node.kind == 'sequence':
        for child in node.children:
            r = tick(child, bb)
            if r != SUCCESS:  # 실패·진행 중이면 중단
                return r
        return SUCCESS
    if node.kind == 'selector':
        for child in node.children:
            r = tick(child, bb)
            if r != FAILURE:  # 성공·진행 중이면 중단
                return r
        return FAILURE
    if node.kind == 'inverter':  # 데코레이터 예
        r = tick(node.child, bb)
        flip = {SUCCESS: FAILURE, FAILURE: SUCCESS}
        return flip.get(r, r)  # RUNNING은 그대로

belady-anomaly.pseudocode:
def fifo_faults(refs, n):
    frames, faults = [], 0
    for p in refs:
        if p not in frames:
            faults += 1
            if len(frames) == n:
                frames.pop(0)  # 가장 먼저 적재된 페이지 교체
            frames.append(p)
    return faults

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]
print(fifo_faults(refs, 3))  # 9
print(fifo_faults(refs, 4))  # 10: 프레임을 늘렸는데 부재 증가

bellman-equation.pseudocode:
def value_iteration(S, A, P, R, gamma, eps=1e-6):
    # P(s, a): [(s2, prob), ...], 모든 s에 행동 1개 이상
    V = {s: 0.0 for s in S}
    while True:
        delta = 0.0
        for s in S:
            # 벨만 최적 방정식: 행동에 대해 max
            v = max(sum(p * (R(s, a, s2) + gamma * V[s2])
                        for s2, p in P(s, a))
                    for a in A(s))
            delta = max(delta, abs(v - V[s]))
            V[s] = v
        if delta < eps:  # 가치 변화가 충분히 작으면 수렴
            return V

bellman-ford-algorithm.pseudocode:
def bellman_ford(V, edges, src):
    INF = float('inf')
    dist = [INF] * V
    dist[src] = 0
    for _ in range(V - 1):  # 최대 V-1개 간선 경로
        updated = False
        for u, v, w in edges:  # 모든 간선 완화
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # 조기 종료
    for u, v, w in edges:  # V번째 검사
        if dist[u] + w < dist[v]:
            return None  # 음수 사이클 존재
    return dist  # 시간복잡도 O(VE)

bernstein-polynomial.pseudocode:
def bernstein(i, n, t):
    # B(i,n)(t) = C(n,i)·(1-t)^(n-i)·t^i
    return comb(n, i) * (1 - t) ** (n - i) * t ** i

def bezier_point(P, t):
    n = len(P) - 1  # 차수 = 제어점 수 - 1
    return sum(bernstein(i, n, t) * P[i]
               for i in range(n + 1))

def de_casteljau(P, t):
    # 같은 점을 선형 보간 반복으로 계산 (수치 안정)
    pts = list(P)
    while len(pts) > 1:
        pts = [(1 - t) * pts[k] + t * pts[k + 1]
               for k in range(len(pts) - 1)]
    return pts[0]
